def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Helpers
    def opponent_action(i):
        return history[i][1]

    def own_action(i):
        return history[i][0]

    # Short windows
    recent_len = 10 if n >= 10 else n
    recent = history[-recent_len:]
    opp_recent_c = sum(1 for _, o in recent if o == 'C')
    my_recent_c = sum(1 for m, _ in recent if m == 'C')
    opp_recent_d = recent_len - opp_recent_c
    opp_c_total = sum(1 for _, o in history if o == 'C')
    my_c_total = sum(1 for m, _ in history if m == 'C')
    opp_d_total = n - opp_c_total
    remaining = 100 - n

    last_my = own_action(n - 1)
    last_opp = opponent_action(n - 1)

    # Defection streak at end for opponent
    opp_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run += 1
        else:
            break

    # Cooperation streak at end for opponent
    opp_c_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_run += 1
        else:
            break

    # Our own recent defection run
    my_run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_run_d += 1
        else:
            break

    # Detect mutual cooperation quality
    mutual_cc = sum(1 for m, o in history if m == 'C' and o == 'C')

    # 1) Very endgame exploitation of pure/near-pure cooperators
    if remaining <= 3:
        if opp_c_total >= n - 2 and n >= 8:
            return 'D'
        # If opponent has been defecting heavily, keep defecting to limit losses
        if opp_d_total >= n - max(1, n // 8):
            return 'D'
        # If they retaliate quickly, avoid triggering; else take last shot
        if opp_c_total * 5 >= n * 4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # 2) Pure always-cooperator: exploit heavily after trust-building
    if n >= 6 and opp_d_total == 0:
        # Build trust for a while, then farm
        if n < 10:
            return 'C'
        return 'D'

    # 3) Pure always-defector: best response is defect
    if n >= 4 and opp_c_total == 0:
        return 'D'

    # 4) Opponent mostly cooperative: cooperate, occasional probe, but preserve CC
    if opp_c_total >= int(0.85 * n) and n >= 8:
        # Defect in last few rounds handled above
        if remaining <= 6:
            return 'D'
        # Very rare probe in mid-game if we still have many rounds to repair
        if remaining > 20 and n % 23 == 0 and opp_run == 0:
            return 'D'
        return 'C'

    # 5) Strict reciprocator detection (TFT-like): they copy our previous move often
    if n >= 8:
        matches = 0
        checked = 0
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                matches += 1
            checked += 1
        if checked > 0 and matches >= checked - 2:
            # Against strict reciprocator, alternating D/C exploits but risks spirals.
            # Safer: cooperate mostly, defect when we can recover cheaply.
            if remaining <= 2:
                return 'D'
            # If our last move was D, cooperate to return to CC
            if last_my == 'D':
                return 'C'
            # Otherwise cooperate, unless very late and partner still cooperative
            if remaining > 15:
                return 'C'
            # Late: try a D then C pattern carefully
            if last_opp == 'C' and n % 2 == 0:
                return 'D'
            return 'C'

    # 6) Grim-trigger detection: all D after our first D
    if n >= 5:
        first_my_d = -1
        for i in range(n):
            if history[i][0] == 'D':
                first_my_d = i
                break
        if first_my_d >= 0 and first_my_d < n - 1:
            after = history[first_my_d + 1:]
            if after and all(o == 'D' for _, o in after):
                return 'D'

    # 7) Opponent heavily defective recently: retaliate firmly
    if opp_run >= 3:
        # Long defection chain; try occasional conciliatory gesture to break deadlock
        if n > 25 and opp_run >= 3 and opp_c_total >= n // 4:
            if rng.random() < 0.12:
                return 'C'
        return 'D'

    if opp_run == 2:
        # Punish once more, but be willing to repair if they have cooperative history
        if opp_c_total >= n // 3 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # 8) Opponent just defected once
    if last_opp == 'D':
        # If we've been defecting too long, offer cooperation
        if my_run_d >= 3:
            return 'C'
        # If recent window shows opponent mostly cooperative, punish briefly then forgive
        if opp_recent_c >= opp_recent_d:
            # Alternate punishment and conciliation to restore CC
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Against moderately defecting opponent, retaliate
        if opp_recent_d >= 4:
            return 'D'
        # Otherwise punish once
        if last_my == 'D':
            return 'C'
        return 'D'

    # 9) Opponent just cooperated
    if last_opp == 'C':
        # If we defected last, return to cooperation to rebuild
        if last_my == 'D':
            return 'C'
        # Preserve mutual cooperation
        return 'C'

    # Default: cooperate to enable mutual cooperation
    return 'C'
